package com.finanscore.credit.infrastructure; import com.finanscore.credit.domain.CreditRequestStatus;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.UUID;
@Entity @Table(name="credit_request") public class CreditRequestEntity{ @Id public UUID id; @Column(name="user_id",nullable=false) public Long userId; @Column(name="correlation_id",nullable=false,length=36) public String correlationId; @Column(name="product_code",nullable=false,length=40) public String productCode; @Column(nullable=false,precision=18,scale=2) public BigDecimal amount; @Column(nullable=false,length=8) public String currency; @Column(name="term_months",nullable=false) public int termMonths; @Column(nullable=false,length=150) public String purpose; @Column(nullable=false) public boolean consent; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) public CreditRequestStatus status; @Column(name="score_value") public Integer scoreValue; @Column(length=40) public String recommendation; @Column(name="model_version",length=20) public String modelVersion; @Column(name="report_id") public UUID reportId; @Column(name="created_at",nullable=false) public Instant createdAt; @Column(name="updated_at",nullable=false) public Instant updatedAt; }
